import type { Metadata } from 'next'
import { notFound } from 'next/navigation'
import { BackButton } from '@/components/BackButton'
import type { Comment, Post } from '@/types/blog'

// `getStaticProps` + `revalidate: 300` -> segment-level ISR config.
export const revalidate = 300

// `getStaticPaths({ fallback: 'blocking' })` -> params outside
// `generateStaticParams` are rendered on demand and then cached.
export const dynamicParams = true

interface BlogPostPageProps {
  /** Route params are async in the App Router and must be awaited. */
  params: Promise<{ id: string }>
}

/** `getStaticPaths` -> `generateStaticParams`. */
export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const res = await fetch('https://jsonplaceholder.typicode.com/posts')
  const posts: Post[] = await res.json()

  return posts.slice(0, 10).map((post) => ({ id: post.id.toString() }))
}

/**
 * Fetches a post, returning `null` when it does not exist. Repeated calls
 * within one request are deduplicated by the App Router's fetch cache, so
 * `generateMetadata` and the page share a single network request.
 */
async function getPost(id: string): Promise<Post | null> {
  const res = await fetch(`https://jsonplaceholder.typicode.com/posts/${id}`)
  if (!res.ok) return null

  const post: Post | Record<string, never> = await res.json()
  return 'id' in post ? (post as Post) : null
}

async function getComments(id: string): Promise<Comment[]> {
  const res = await fetch(
    `https://jsonplaceholder.typicode.com/posts/${id}/comments`
  )
  if (!res.ok) return []

  return res.json()
}

/** `next/head` -> the Metadata API. */
export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getPost(id)

  if (!post) return {}

  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params

  const [post, comments] = await Promise.all([getPost(id), getComments(id)])

  // `return { notFound: true }` -> the `notFound()` helper, which renders
  // the nearest `not-found` boundary with a 404 status.
  if (!post) {
    notFound()
  }

  return (
    <article>
      <BackButton>← Back</BackButton>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

