'use client'

import { useEffect } from 'react'

export interface ErrorBoundaryProps {
  error: Error & { digest?: string }
  /** Re-renders the failed segment. */
  reset: () => void
}

/**
 * `pages/_error.js` -> the App Router `error` boundary. There is no
 * `getInitialProps`/`statusCode` here: 404s go to `not-found.tsx`, and this
 * boundary catches runtime errors thrown while rendering a segment.
 */
export default function Error({ error, reset }: ErrorBoundaryProps) {
  useEffect(() => {
    console.error(error)
  }, [error])

  return (
    <div className="error-page">
      <h1>An error occurred</h1>
      <p>Sorry, something went wrong.</p>
      <button onClick={() => reset()}>Try again</button>
    </div>
  )
}

