import { NextResponse, type NextRequest } from 'next/server'
import type { ApiError, ApiPost, PostInput } from '@/types/blog'

/**
 * `pages/api/posts/index.js` -> an App Router Route Handler.
 *
 * Each HTTP method is its own export; Next.js answers any other method with
 * `405` and the correct `Allow` header, so the manual `res.setHeader('Allow', …)`
 * fallback from the Pages Router handler is no longer needed.
 */
export async function GET(): Promise<NextResponse<ApiPost[]>> {
  // Simulate fetching posts
  const posts: ApiPost[] = [
    { id: 1, title: 'First Post', content: 'This is the first post' },
    { id: 2, title: 'Second Post', content: 'This is the second post' },
  ]

  return NextResponse.json(posts, { status: 200 })
}

export async function POST(
  request: NextRequest
): Promise<NextResponse<ApiPost | ApiError>> {
  // `req.body` was pre-parsed by the Pages Router; route handlers read the
  // request stream explicitly, which throws on a malformed payload.
  let body: PostInput
  try {
    body = (await request.json()) as PostInput
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  if (!title || !content) {
    return NextResponse.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  // Simulate creating a post
  const newPost: ApiPost = {
    id: Date.now(),
    title,
    content,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(newPost, { status: 201 })
}

