import { NextResponse, type NextRequest } from 'next/server'
import type { ApiError, ApiPost, PostInput } from '@/types/blog'

interface RouteContext {
  /** Dynamic segments are async in the App Router and must be awaited. */
  params: Promise<{ id: string }>
}

/**
 * `pages/api/posts/[id].js` -> an App Router Route Handler. `req.query.id` is
 * now the awaited `params.id`, and unsupported methods get a framework-provided
 * `405` with the `Allow` header derived from the exports below.
 */
export async function GET(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost>> {
  const { id } = await params

  // Simulate fetching a single post
  const post: ApiPost = {
    id: parseInt(id),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return NextResponse.json(post, { status: 200 })
}

export async function PUT(
  request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<ApiPost | ApiError>> {
  const { id } = await params

  let body: PostInput
  try {
    body = (await request.json()) as PostInput
  } catch {
    return NextResponse.json({ error: 'Invalid JSON body' }, { status: 400 })
  }

  const { title, content } = body

  // Simulate updating a post
  const updatedPost: ApiPost = {
    id: parseInt(id),
    title: title || `Post ${id}`,
    content: content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return NextResponse.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: NextRequest,
  { params }: RouteContext
): Promise<NextResponse<{ message: string }>> {
  const { id } = await params

  // Simulate deleting a post
  return NextResponse.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

